project_keys = [str(i) for i in range(1, 111)]
if not len(project_keys) == len(project_names) == len(capital) == len(npv) == 110:
    raise ValueError('Project data length mismatch.')
capital_dict = {project_keys[i]: capital[i] for i in range(110)}
npv_dict = {project_keys[i]: npv[i] for i in range(110)}
m = gp.Model('Project_Selection')
x_vars = m.addVars(project_keys, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((npv_dict[i] * x_vars[i] for i in project_keys)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((capital_dict[i] * x_vars[i] for i in project_keys)) <= 1000, name='budget')
m.addConstr(x_vars['4'] + x_vars['7'] <= 1, name='mutual_excl_4_7')
m.addConstr(x_vars['6'] <= x_vars['1'], name='prereq_6_1')
m.addConstr(x_vars['10'] <= x_vars['5'], name='contingent_10_5')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')